self.addEventListener("install",()=>self.skipWaiting());
self.addEventListener("activate",(e)=>e.waitUntil(self.clients.claim()));
self.addEventListener("fetch",(e)=>{
  const u=e.request.url, l=M[u];
  if(l){e.respondWith(fetch(l).catch(()=>fetch(e.request)));return}
  const q=u.indexOf("?");
  if(q>0){
    const bl=M[u.slice(0,q)], rm=u.slice(q).match(/[?&]range=(\d+)-(\d+)/);
    if(bl&&rm){e.respondWith((async()=>{try{
      const buf=await (await fetch(bl)).arrayBuffer();
      return new Response(buf.slice(+rm[1],+rm[2]+1),{status:200});
    }catch(_){return fetch(e.request)}})());return}
    if(bl){e.respondWith(fetch(bl).catch(()=>fetch(e.request)))}
  }
});
